// 自動ダミー選択肢生成付きの WordItem & SentenceItem 変換
export const TARGET1800_WORDS: (WordItem & {
  level: number;
  origLevel: number;
  num: string;
  stageSlug: string;
})[] = TARGET1800_ENTRIES.map((entry, idx) => {
  const sameLevel = TARGET1800_ENTRIES.filter(
    (other) => other.level === entry.level && other.num !== entry.num
  );
  const samePos = sameLevel.filter(
    (other) => other.partOfSpeech === entry.partOfSpeech
  );
  const pool = samePos.length >= 3 ? samePos : sameLevel;
  const d1 = pool[(idx * 3 + 1) % pool.length];
  const d2 = pool[(idx * 3 + 7) % pool.length];
  const d3 = pool[(idx * 3 + 13) % pool.length];

  return {
    id: `target1800_${entry.num}`,
    num: entry.num,
    level: entry.level,
    origLevel: entry.origLevel,
    stageSlug: entry.stageSlug,
    english: entry.english,
    japanese: entry.japanese,
    phonetic: entry.phonetic,
    partOfSpeech: `ターゲット1800 #${entry.num} (${entry.partOfSpeech})`,
    grade: "ターゲット1800",
    distractorsJa: [d1.japanese, d2.japanese, d3.japanese],
    distractorsEn: [d1.english, d2.english, d3.english],
    tip: entry.tip,
    exampleSentenceEn: entry.sentenceEn.join(" "),
    exampleSentenceJa: entry.sentenceJa,
  };
});

export const TARGET1800_SENTENCES: (SentenceItem & {
  level: number;
  origLevel: number;
  num: string;
  stageSlug: string;
})[] = TARGET1800_ENTRIES.map((entry, idx) => {
  const other1 =
    TARGET1800_ENTRIES[(idx + 5) % TARGET1800_ENTRIES.length].english;
  const other2 =
    TARGET1800_ENTRIES[(idx + 11) % TARGET1800_ENTRIES.length].english;

  return {
    id: `s_target1800_${entry.num}`,
    num: entry.num,
    level: entry.level,
    origLevel: entry.origLevel,
    stageSlug: entry.stageSlug,
    englishTokens: entry.sentenceEn,
    distractorTokens: [other1, other2],
    japanese: entry.sentenceJa,
    targetWordIds: [`target1800_${entry.num}`],
    grade: "ターゲット1800",
    grammarPoint: `【ターゲット1800 #${entry.num} / Lv.${String(entry.level).padStart(2, "0")}】${entry.english} ＝ ${entry.japanese}`,
  };
});
